import gzip
import json
import random
import string
import uuid
import time

from locust import HttpUser, task, between


# 🔹 Real base64 screenshots (truncated for readability — paste full strings)
SCREENSHOTS = [
    "",  # paste full first base64 here
    ""   # paste full second base64 here
]


def generate_mobile_recording(platform="android", num_screenshots=3):
    session_id = str(uuid.uuid4()).upper() if platform == "ios" else str(uuid.uuid4())
    user_id = f"user-{''.join(random.choices(string.ascii_lowercase, k=8))}"
    project_id = f"proj-{''.join(random.choices(string.ascii_lowercase, k=6))}"
    base_ts = int(time.time() * 1000)

    if platform == "ios":
        img_format = "webp"
        screen_w, screen_h = 390, 844
    else:
        img_format = "webp"
        screen_w, screen_h = 393, 852

    snapshot_items = []
    for i in range(num_screenshots):
        snapshot_items.append({
            "type": 2,
            "timestamp": base_ts + (i * 1000),
            "data": {
                "wireframes": [{
                    "type": "screenshot",
                    "id": random.randint(1000000, 9999999999),
                    "base64": f"data:image/{img_format};base64,{SCREENSHOTS[i % len(SCREENSHOTS)]}",
                    "width": screen_w,
                    "height": screen_h,
                    "x": 0,
                    "y": 0,
                }],
                "initialOffset": {"left": 0, "top": 0},
            },
        })

    return {
        "event": "snapshot",
        "user_id": user_id,
        "project_id": project_id,
        "timestamp": f"{int(time.time())}",
        "properties": {
            "session_id": session_id,
            "snapshot_source": "mobile",
            "snapshot_data": snapshot_items,
        },
    }


# 🔹 Pre-generate payloads
print("Pre-generating payloads...")
ANDROID_PAYLOADS = []
IOS_PAYLOADS = []

for _ in range(25):
    for platform, pool in [("android", ANDROID_PAYLOADS), ("ios", IOS_PAYLOADS)]:
        payload = generate_mobile_recording(
            platform=platform,
            num_screenshots=random.randint(10, 10),  # realistic variation
        )
        raw = json.dumps(payload).encode("utf-8")
        compressed = gzip.compress(raw)
        pool.append(compressed)

print(f"Android payloads: {len(ANDROID_PAYLOADS)}, "
      f"avg compressed: {sum(len(p) for p in ANDROID_PAYLOADS) // len(ANDROID_PAYLOADS) // 1024} KB")
print(f"iOS payloads: {len(IOS_PAYLOADS)}, "
      f"avg compressed: {sum(len(p) for p in IOS_PAYLOADS) // len(IOS_PAYLOADS) // 1024} KB")


class AndroidUser(HttpUser):
    wait_time = between(0.01, 0.05)
    host = "http://localhost:3400"
    weight = 7

    @task
    def send_recording(self):
        payload = random.choice(ANDROID_PAYLOADS)
        self.client.post(
            "/s/",
            data=payload,
            headers={
                "Content-Type": "application/json",
                "Content-Encoding": "gzip",
            },
            name="/s/ (android)",
        )


class IOSUser(HttpUser):
    wait_time = between(0.01, 0.05)
    host = "http://localhost:3400"
    weight = 3

    @task
    def send_recording(self):
        payload = random.choice(IOS_PAYLOADS)
        self.client.post(
            "/s/",
            data=payload,
            headers={
                "Content-Type": "application/json",
                "Content-Encoding": "gzip",
            },
            name="/s/ (ios)",
        )